/// <summary>
/// The <c>AVAWHSRFPassthroughCls_Extension</c> provides strongly typed convenience methods to the <c>WhsrfPassthrough</c> class.
/// </summary>
[
    ExtensionOf(classStr(WhsrfPassthrough))
]
final class AVAWHSRFPassthroughCls_Extension
{
}

Method.Source:
/// <summary> 
/// Parm method for printer code in the WhsrfPassthrough
/// </summary>
/// <param name = "_printerCode">
/// string text of the printer as Code option
/// </param> 
/// <returns> 
/// string text of the <c>printerCode</c> option 
/// </returns> 
public str avaParmPrinterCode(str _printerCode = '')
{ 
    if (!prmIsDefault(_printerCode))
    { 
        this.insert(ProcessGuideDataTypeNames::AVAPrinterCode, _printerCode);
    } 

    return this.lookupStr(ProcessGuideDataTypeNames::AVAPrinterCode);
}

/// <summary>
/// Parm method for full mode in the WhsrfPassthrough
/// </summary>
/// <param name = "_fullMode">
/// string text of the full mode
/// </param>
/// <returns>
/// string text of the <c>fullMode</c> option
/// </returns>
public str avaParmFullMode(str _fullMode = '')
{
    if (!prmIsDefault(_fullMode))
    {
        this.insert(ProcessGuideDataTypeNames::AVAFullMode, _fullMode);
    }

    return this.lookupStr(ProcessGuideDataTypeNames::AVAFullMode);
}

